    kookSettingsSaved: "KOOK настроек сохранено.",
    discordTemplateVarsHint: "Переменные шаблона: {serverName} {wipeName} {startedAt} {nextWipeAt} {directConnect} {vipUrl} {mapLink} {rustMapsLink} {kdaUrl} {notes}",
    botKdaTemplateBody: "Введите SteamID, имя участника или ссылку профиля, чтобы запросить KDA текущего сервера.\nВозвращает убийства, смерти, KD/KDA, время онлайн и данные текущего Wipe.\nОтвечает только в настроенном канале запросов KDA; если канал не указан, разрешены все каналы.",
    botMemberRegistrationTemplateTitle: "Регистрация NB Clan и VIP",
    botMemberRegistrationTemplateBody: "Участники с настроенной ролью регистрации могут зарегистрировать здесь свои данные SteamID и VIP.\nДля новых участников: нажмите «Зарегистрировать участника», выберите специальность, затем отправьте информацию о SteamID и VIP одним потоком. Ваша роль решает, в какую команду вы войдете.\nУже зарегистрировано: используйте кнопку обновления VIP справа, чтобы поддерживать актуальность типа и дат каждого сервера VIP.\nСистема отправляет напоминание Discord в DM за 3 дня до истечения срока действия VIP.",
    botRankingTemplateTitle: "Текущий рейтинг участников сервера · {metric} Топ {limit}",
    botRankingTemplateBody: "Показывает рейтинг лучших участников текущего сервера {limit}.\nВ рейтинговой карточке указаны команды, SteamID, KDA, убийства, смерти, время онлайн и другие основные данные.\nNB Clan · Используйте кнопки ниже, чтобы переключить тип рейтинга",
    botMapTemplateTitle: "Карта {serverName}",
    botMapTemplateBody: "Информация о карте текущего сервера {serverName}.\nВключает превью карты, ссылку RustMaps, ссылку для скачивания карты и адрес прямого подключения сервера.\nПосле изменения карты или Wipe можно снова отправить карточку в настроенный канал.",
    botKookKdaTemplateBody: "Запрос KDA текущего сервера в настроенном канале KOOK.\nПоддерживает SteamID, имя участника или ссылку профиля.\nВозвращает убийства, смерти, KD/KDA, время онлайн и данные текущего Wipe.",
    botKookWipeTemplateTitle: "KOOK wipe регистрация",
    botKookWipeTemplateBody: "KOOK wipe карточка регистрационного канала.\nУчастники могут сообщить о своем статусе вовремя, опоздании или неуверенности в KOOK.\nИспользуется для текущей статистики посещаемости wipe.",
