    discordTemplateVarsHint: "Şablon değişkenleri: {serverName} {wipeName} {startedAt} {nextWipeAt} {directConnect} {vipUrl} {mapLink} {rustMapsLink} {kdaUrl} {notes}",
    botKdaTemplateBody: "Mevcut sunucu KDA'sını sorgulamak için SteamID, üye adı veya profil bağlantısı girin.\nÖldürme, ölüm, KD/KDA, çevrimiçi süre ve mevcut Wipe verilerini döndürür.\nYalnızca yapılandırılmış KDA sorgu kanalında yanıt verir; kanal boşsa tüm kanallara izin verilir.",
    botMemberRegistrationTemplateTitle: "NB Clan Kaydı ve VIP",
    botMemberRegistrationTemplateBody: "Yapılandırılmış kayıt rolüne sahip üyeler, SteamID ve VIP bilgilerini buraya kaydedebilirler.\nYeni üyeler: Üyeyi Kaydet'e tıklayın, bir uzmanlık seçin ve ardından SteamID ve VIP bilgilerini tek bir akışta gönderin. Rolünüz hangi takıma gireceğinizi belirler.\nZaten kayıtlı: Her sunucunun VIP türünü ve tarihini güncel tutmak için sağdaki VIP güncelleme düğmesini kullanın.\nSistem, VIP süresinin dolmasından 3 gün önce bir Discord DM hatırlatıcısı gönderir.",
    botRankingTemplateTitle: "Mevcut sunucu üye sıralaması · {metric} En iyi {limit}",
    botRankingTemplateBody: "Geçerli sunucu üyesinin sıralamasında En Üstteki {limit}'yi gösterir.\nSıralama kartında takım, SteamID, KDA, öldürmeler, ölümler, çevrimiçi süre ve diğer temel veriler bulunur.\nNB Clan · Sıralama türünü değiştirmek için aşağıdaki düğmeleri kullanın",
    botMapTemplateTitle: "{serverName} haritası",
    botMapTemplateBody: "{serverName} için harita bilgileri.\nHarita önizlemesini, RustMaps bağlantısını, harita indirme bağlantısını ve sunucu doğrudan bağlantı adresini içerir.\nHarita veya Wipe bilgileri değiştikten sonra kartı yapılandırılmış kanala yeniden gönderin.",
    botKookKdaTemplateBody: "Yapılandırılmış KOOK kanalında mevcut sunucu KDA'sını sorgular.\nSteamID, üye adı veya profil bağlantısını destekler.\nÖldürme, ölüm, KD/KDA, çevrimiçi süre ve mevcut Wipe verilerini döndürür.",
