    botKdaTemplateBody: "ป้อน SteamID ชื่อสมาชิก หรือลิงก์โปรไฟล์เพื่อค้นหา KDA ของเซิร์ฟเวอร์ปัจจุบัน\nส่งคืนจำนวนฆ่า การตาย KD/KDA เวลาออนไลน์ และข้อมูล Wipe ปัจจุบัน\nตอบกลับเฉพาะในช่องค้นหา KDA ที่กำหนดไว้ หากเว้นช่องว่างไว้จะอนุญาตทุกช่อง",
    botMemberRegistrationTemplateTitle: "การลงทะเบียน NB Clan & VIP",
    botMemberRegistrationTemplateBody: "สมาชิกที่มีบทบาทการลงทะเบียนที่กำหนดค่าไว้สามารถลงทะเบียนข้อมูล SteamID และ VIP ได้ที่นี่\nสมาชิกใหม่: คลิกลงทะเบียนสมาชิก เลือกความเชี่ยวชาญ จากนั้นส่งข้อมูล SteamID และ VIP ในขั้นตอนเดียว บทบาทของคุณเป็นตัวกำหนดว่าคุณจะเข้าร่วมทีมใด\nลงทะเบียนแล้ว: ใช้ปุ่มอัปเดต VIP ทางด้านขวาเพื่อให้แต่ละเซิร์ฟเวอร์ VIP ประเภทและวันที่เป็นปัจจุบัน\nระบบจะส่งการแจ้งเตือน DM Discord 3 วันก่อนหมดอายุ VIP",
    botRankingTemplateTitle: "อันดับสมาชิกเซิร์ฟเวอร์ปัจจุบัน · {metric} สูงสุด {limit}",
    botRankingTemplateBody: "แสดงอันดับสมาชิกเซิร์ฟเวอร์ปัจจุบันสูงสุด {limit}\nการ์ดจัดอันดับประกอบด้วยทีม, SteamID, KDA, การสังหาร, การตาย, เวลาออนไลน์ และข้อมูลหลักอื่นๆ\nNB Clan · ใช้ปุ่มด้านล่างเพื่อเปลี่ยนประเภทการจัดอันดับ",
    botMapTemplateTitle: "แผนที่ {serverName}",
    botMapTemplateBody: "ข้อมูลแผนที่สำหรับเซิร์ฟเวอร์ {serverName}\nรวมภาพตัวอย่างแผนที่ ลิงก์ RustMaps ลิงก์ดาวน์โหลดแผนที่ และที่อยู่เชื่อมต่อตรงของเซิร์ฟเวอร์\nหลังจากข้อมูลแผนที่หรือ Wipe เปลี่ยน ให้ส่งการ์ดไปยังช่องที่กำหนดอีกครั้ง",
    botKookKdaTemplateBody: "ค้นหา KDA ของเซิร์ฟเวอร์ปัจจุบันในช่อง KOOK ที่กำหนดไว้\nรองรับ SteamID ชื่อสมาชิก หรือลิงก์โปรไฟล์\nส่งคืนจำนวนฆ่า การตาย KD/KDA เวลาออนไลน์ และข้อมูล Wipe ปัจจุบัน",
    botKookWipeTemplateTitle: "KOOK wipe การลงทะเบียน",
    botKookWipeTemplateBody: "KOOK wipe การ์ดช่องทางการลงทะเบียน\nสมาชิกสามารถส่งสถานะตรงเวลา ล่าช้า หรือไม่แน่ใจใน KOOK\nใช้สำหรับสถิติการเข้างานปัจจุบัน wipe",
