Object.assign(COPY.zh, {"kookBindTitle": "绑定你的 Steam 账号", "kookBindHint": "首次登录需拥有 NB Clan(CN) 或 EU 角色。登录你本人的 Steam 账号后，系统会自动匹配已有成员资料，没有则创建。无需填写 Steam ID。", "kookSteamInputLabel": "你的 Steam ID 或 Steam 主页链接", "kookConfirmSteam": "登录 Steam 并绑定", "kookRestartLogin": "重新使用 KOOK 登录", "kookRoleRequired": "你需要拥有 NB Clan(CN) 或 EU 角色才能登录。", "kookRoleCheckFailed": "暂时无法核实 KOOK 角色，请稍后重试或联系管理员。", "kookBindingConflict": "KOOK 或 Steam 已存在其他绑定，请联系管理员处理。", "kookSteamVerifyFailed": "Steam 身份确认失败，请重新确认。", "kookSteamMismatch": "当前 Steam 账号与输入的 ID 不一致，请登录正确的 Steam 账号。", "kookOnboardingExpired": "本次绑定已过期，请重新使用 KOOK 登录。", "kookBindingBusy": "正在处理绑定，请稍后再试。", "kookSteamInputInvalid": "请输入有效的 Steam ID 或 Steam 主页链接。"});
Object.assign(COPY.en, {"kookBindTitle": "Link your Steam account", "kookBindHint": "You need the NB Clan(CN) or EU role. Sign in to your own Steam account to match an existing member profile or create one. No Steam ID entry is needed.", "kookSteamInputLabel": "Your Steam ID or profile URL", "kookConfirmSteam": "Sign in to Steam and link", "kookRestartLogin": "Sign in with KOOK again", "kookRoleRequired": "You need the NB Clan(CN) or EU role to sign in.", "kookRoleCheckFailed": "Unable to verify KOOK roles. Try again later or contact an administrator.", "kookBindingConflict": "This KOOK or Steam account has another link. Contact an administrator.", "kookSteamVerifyFailed": "Steam identity verification failed. Please try again.", "kookSteamMismatch": "The signed-in Steam account does not match the ID you entered. Sign in to the correct account.", "kookOnboardingExpired": "This linking session expired. Sign in with KOOK again.", "kookBindingBusy": "Linking is in progress. Please try again shortly.", "kookSteamInputInvalid": "Enter a valid Steam ID or Steam profile URL."});
Object.assign(COPY.ru, {"kookBindTitle": "Привяжите аккаунт Steam", "kookBindHint": "Нужна роль NB Clan(CN) или EU. Войдите в свой Steam: мы найдём существующий профиль или создадим новый. Вводить Steam ID не нужно.", "kookSteamInputLabel": "Ваш Steam ID или ссылка на профиль", "kookConfirmSteam": "Войти в Steam и привязать", "kookRestartLogin": "Войти через KOOK снова", "kookRoleRequired": "Для входа нужна роль NB Clan(CN) или EU.", "kookRoleCheckFailed": "Не удалось проверить роли KOOK. Повторите позже или обратитесь к администратору.", "kookBindingConflict": "Этот KOOK или Steam уже связан с другим аккаунтом. Обратитесь к администратору.", "kookSteamVerifyFailed": "Не удалось подтвердить Steam. Повторите попытку.", "kookSteamMismatch": "Аккаунт Steam не совпадает с введённым ID. Войдите в нужный аккаунт.", "kookOnboardingExpired": "Сеанс привязки истёк. Войдите через KOOK снова.", "kookBindingBusy": "Привязка выполняется. Повторите позже.", "kookSteamInputInvalid": "Введите корректный Steam ID или ссылку на профиль."});
Object.assign(COPY.tr, {"kookBindTitle": "Steam hesabınızı bağlayın", "kookBindHint": "NB Clan(CN) veya EU rolü gerekir. Kendi Steam hesabınıza giriş yapın; mevcut üye profili eşleştirilir veya yenisi oluşturulur. Steam ID girmeniz gerekmez.", "kookSteamInputLabel": "Steam ID veya profil bağlantınız", "kookConfirmSteam": "Steam ile giriş yap ve bağla", "kookRestartLogin": "KOOK ile tekrar giriş yap", "kookRoleRequired": "Giriş için NB Clan(CN) veya EU rolü gerekir.", "kookRoleCheckFailed": "KOOK rolleri doğrulanamadı. Daha sonra deneyin veya yöneticiye başvurun.", "kookBindingConflict": "Bu KOOK veya Steam hesabı başka bir hesaba bağlı. Yöneticiye başvurun.", "kookSteamVerifyFailed": "Steam doğrulaması başarısız. Tekrar deneyin.", "kookSteamMismatch": "Steam hesabı girdiğiniz ID ile eşleşmiyor. Doğru hesaba giriş yapın.", "kookOnboardingExpired": "Bağlama oturumu sona erdi. KOOK ile tekrar giriş yapın.", "kookBindingBusy": "Bağlama işlemi sürüyor. Biraz sonra tekrar deneyin.", "kookSteamInputInvalid": "Geçerli bir Steam ID veya profil bağlantısı girin."});
Object.assign(COPY.th, {"kookBindTitle": "เชื่อมโยงบัญชี Steam", "kookBindHint": "ต้องมีบทบาท NB Clan(CN) หรือ EU เข้าสู่บัญชี Steam ของคุณ ระบบจะจับคู่โปรไฟล์สมาชิกเดิมหรือสร้างใหม่ โดยไม่ต้องกรอก Steam ID", "kookSteamInputLabel": "Steam ID หรือลิงก์โปรไฟล์ของคุณ", "kookConfirmSteam": "เข้าสู่ Steam และเชื่อมโยง", "kookRestartLogin": "เข้าสู่ระบบด้วย KOOK อีกครั้ง", "kookRoleRequired": "ต้องมีบทบาท NB Clan(CN) หรือ EU จึงจะเข้าสู่ระบบได้", "kookRoleCheckFailed": "ไม่สามารถตรวจสอบบทบาท KOOK ได้ โปรดลองใหม่หรือติดต่อผู้ดูแล", "kookBindingConflict": "บัญชี KOOK หรือ Steam นี้มีการเชื่อมโยงอื่นแล้ว โปรดติดต่อผู้ดูแล", "kookSteamVerifyFailed": "ยืนยัน Steam ไม่สำเร็จ โปรดลองอีกครั้ง", "kookSteamMismatch": "บัญชี Steam ไม่ตรงกับ ID ที่กรอก โปรดเข้าสู่บัญชีที่ถูกต้อง", "kookOnboardingExpired": "เซสชันหมดอายุ โปรดเข้าสู่ระบบด้วย KOOK อีกครั้ง", "kookBindingBusy": "กำลังเชื่อมโยง โปรดลองอีกครั้งในภายหลัง", "kookSteamInputInvalid": "โปรดกรอก Steam ID หรือลิงก์โปรไฟล์ที่ถูกต้อง"});
Object.assign(COPY.ko, {"kookBindTitle": "Steam 계정 연결", "kookBindHint": "NB Clan(CN) 또는 EU 역할이 필요합니다. 본인의 Steam 계정으로 로그인하면 기존 회원 프로필에 연결하거나 새로 만듭니다. Steam ID를 입력할 필요가 없습니다.", "kookSteamInputLabel": "본인의 Steam ID 또는 프로필 URL", "kookConfirmSteam": "Steam 로그인 및 연결", "kookRestartLogin": "KOOK으로 다시 로그인", "kookRoleRequired": "로그인하려면 NB Clan(CN) 또는 EU 역할이 필요합니다.", "kookRoleCheckFailed": "KOOK 역할을 확인할 수 없습니다. 나중에 다시 시도하거나 관리자에게 문의하세요.", "kookBindingConflict": "이 KOOK 또는 Steam 계정은 다른 계정에 연결되어 있습니다. 관리자에게 문의하세요.", "kookSteamVerifyFailed": "Steam 확인에 실패했습니다. 다시 시도하세요.", "kookSteamMismatch": "Steam 계정이 입력한 ID와 다릅니다. 올바른 계정으로 로그인하세요.", "kookOnboardingExpired": "연결 세션이 만료되었습니다. KOOK으로 다시 로그인하세요.", "kookBindingBusy": "연결 중입니다. 잠시 후 다시 시도하세요.", "kookSteamInputInvalid": "유효한 Steam ID 또는 프로필 URL을 입력하세요."});

